components/products/add-to-cart:
{{#or product.min_purchase_quantity product.max_purchase_quantity}}
    <div class="min-max-purchase">
{{/or}}
        {{#if product.min_purchase_quantity}}
        <div>
            <dt class="productView-info-name">{{lang 'products.min_purchase_quantity'}}</dt>
            <dd class="productView-info-value">{{lang 'products.purchase_units' quantity=product.min_purchase_quantity}}</dd>
        </div>
        {{/if}}
        {{#if product.max_purchase_quantity}}
        <div>
            <dt class="productView-info-name">{{lang 'products.max_purchase_quantity'}}</dt>
            <dd class="productView-info-value">{{lang 'products.purchase_units' quantity=product.max_purchase_quantity}}</dd>
        </div>
        {{/if}}
{{#or product.min_purchase_quantity product.max_purchase_quantity}}
    </div>
{{/or}}

<div id="add-to-cart-wrapper" class="add-to-cart-wrapper" {{#unless product.can_purchase}}style="display: none"{{/unless}}>
    {{#if theme_settings.show_product_quantity_box}}
        {{inject 'productQuantityErrorMessage'  (lang 'products.quantity_error_message')}}
        <div class="form-field form-field--increments">
            <label class="form-label form-label--alternate" for="qty[]">{{lang 'products.quantity'}}</label>

            <div class="form-increment" data-quantity-change>
                <button class="button button--icon" data-action="dec" type="button">
                    <span class="is-srOnly">{{lang 'products.quantity_decrease'}}</span>
                    <i class="icon" aria-hidden="true">
                        <svg>
                            <use xlink:href="#icon-keyboard-arrow-down"/>
                        </svg>
                    </i>
                </button>
                <input class="form-input form-input--incrementTotal"
                       id="qty[]"
                       name="qty[]"
                       type="tel"
                       value="{{#if product.min_purchase_quantity}}{{product.min_purchase_quantity}}{{else}}1{{/if}}"
                       data-quantity-min="{{product.min_purchase_quantity}}"
                       data-quantity-max="{{product.max_purchase_quantity}}"
                       min="1"
                       pattern="[0-9]*"
                       aria-live="polite">
                <button class="button button--icon" data-action="inc" type="button">
                    <span class="is-srOnly">{{lang 'products.quantity_increase'}}</span>
                    <i class="icon" aria-hidden="true">
                        <svg>
                            <use xlink:href="#icon-keyboard-arrow-up"/>
                        </svg>
                    </i>
                </button>
            </div>
        </div>
    {{/if}}

    <div class="alertBox productAttributes-message" style="display:none">
        <div class="alertBox-column alertBox-icon">
            <icon glyph="ic-success" class="icon" aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"></path></svg></icon>
        </div>
        <p class="alertBox-column alertBox-message"></p>
    </div>
    <div class="product-actions" id="product-actions">
        {{#or customer (if theme_settings.restrict_to_login '!==' true)}}
            <div class="form-action">
                <input
                        id="form-action-addToCart"
                        data-wait-message="{{lang 'products.adding_to_cart'}}"
                        class="button button--primary"
                        type="submit"
                        value="{{#if product.pre_order}}{{lang 'products.pre_order'}}{{else}}{{lang 'products.add_to_cart'}}{{/if}}"
                >
                <span class="product-status-message aria-description--hidden">{{lang 'products.adding_to_cart'}} {{lang 'category.add_cart_announcement'}}</span>
            </div>
        {{/or}}

        <div class="favs-section">
            <!--
            {{#if settings.show_wishlist}}
                {{> components/common/wishlist-dropdown-escapa}}
            {{/if}}
            -->
            {{#unless product.out_of_stock}}
                <div id="b3Container__shoppinglist" class="b3_container__shoppinglist"></div>
            {{/unless}}
        </div>

    </div>
</div>

<script>
    const targetClassName = "b2b-add-to-list";
    const containerDivId = "product-actions";

    function moveToContainer(element) {
        const container = document.getElementById(containerDivId);
        if (container) {
            container.appendChild(element);
            //console.log(`Moved element with class '${targetClassName}' to container with ID '${containerDivId}'.`);
        } else {
           // console.error(`Container with ID '${containerDivId}' not found.`);
        }
    }

    // Create a MutationObserver to watch for DOM changes
    const observer = new MutationObserver((mutationsList) => {
        for (const mutation of mutationsList) {
            if (mutation.type === "childList") {
                // Check added nodes for the target class name
                mutation.addedNodes.forEach((node) => {
                    if (node.nodeType === Node.ELEMENT_NODE && node.classList.contains(targetClassName)) {
                        observer.disconnect();
                        //moveToContainer(node);
                    }
                });
            }
        }
    });

    /*
    observer.observe(document.body, {
        childList: true, 
        subtree: true 
    });
    */
</script>
